/* ============================================
   REDROOM FITNESS — Shared Stylesheet
   Dark, bold, premium HIIT fitness brand
   ============================================ */

/* --- Google Fonts --- */
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

/* --- CSS Custom Properties (OKLCH) --- */
:root {
  /* Brand */
  --red: oklch(62.8% 0.258 29.2);
  --red-hover: oklch(55% 0.24 29.2);
  --red-dark: oklch(45% 0.22 29.2);
  --red-glow: oklch(62.8% 0.258 29.2 / 0.35);

  /* Backgrounds */
  --bg-primary: oklch(8% 0.005 285);
  --bg-secondary: oklch(12% 0.006 285);
  --bg-tertiary: oklch(16% 0.007 285);
  --bg-card: oklch(14% 0.006 285);
  --bg-elevated: oklch(18% 0.007 285);

  /* Text */
  --text-primary: oklch(100% 0 0);
  --text-secondary: oklch(75% 0.01 285);
  --text-tertiary: oklch(55% 0.01 285);
  --text-muted: oklch(45% 0.008 285);

  /* Borders */
  --border-default: oklch(25% 0.01 285);
  --border-subtle: oklch(18% 0.008 285);

  /* Semantic */
  --success: oklch(65% 0.18 145);
  --error: oklch(62.8% 0.258 29.2);

  /* Spacing scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;

  /* Typography */
  --font-heading: 'Oswald', 'Impact', 'Helvetica Neue', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
  --topbar-height: 40px;

  /* Radii */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.5);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.6);
  --shadow-red: 0 0 24px oklch(62.8% 0.258 29.2 / 0.25);

  /* Transitions */
  --ease-fast: 150ms ease;
  --ease-default: 250ms ease;
  --ease-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: 500ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--bg-primary);
  min-height: 100vh;
  padding-top: calc(var(--topbar-height) + var(--nav-height));
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

input {
  font-family: inherit;
  font-size: inherit;
}

/* --- Focus --- */
:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

/* --- Top Bar Promo --- */
.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--topbar-height);
  background: var(--red);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1001;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.topbar a {
  margin-left: var(--space-3);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.topbar a:hover {
  opacity: 0.85;
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: var(--topbar-height);
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-subtle);
  z-index: 1000;
  display: flex;
  align-items: center;
}

.nav__inner {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--red);
  flex-shrink: 0;
}

.nav__logo span {
  color: var(--text-primary);
}

.nav__links {
  display: flex;
  align-items: center;
  gap: var(--space-5);
}

.nav__link {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
  transition: color var(--ease-fast);
  white-space: nowrap;
}

.nav__link:hover,
.nav__link--active {
  color: var(--red);
}

.nav__utility {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.nav__btn {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  transition: all var(--ease-fast);
  white-space: nowrap;
}

.nav__btn--outline {
  border: 1.5px solid var(--text-secondary);
  color: var(--text-primary);
}

.nav__btn--outline:hover {
  border-color: var(--red);
  color: var(--red);
}

.nav__btn--fill {
  background: var(--red);
  color: var(--text-primary);
}

.nav__btn--fill:hover {
  background: var(--red-hover);
  box-shadow: var(--shadow-red);
}

/* Hamburger */
.nav__hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  z-index: 1002;
}

.nav__hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--ease-default);
  transform-origin: center;
}

.nav__hamburger.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav__hamburger.open span:nth-child(2) {
  opacity: 0;
}

.nav__hamburger.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: calc(var(--topbar-height) + var(--nav-height));
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 999;
  flex-direction: column;
  padding: var(--space-6) var(--space-4);
  overflow-y: auto;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav__link {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--space-3) 0;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  transition: color var(--ease-fast);
}

.mobile-nav__link:hover {
  color: var(--red);
}

.mobile-nav__actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-top: var(--space-5);
}

.mobile-nav__btn {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: var(--space-3);
  text-align: center;
  border-radius: var(--radius-sm);
}

.mobile-nav__btn--fill {
  background: var(--red);
  color: var(--text-primary);
}

.mobile-nav__btn--outline {
  border: 1.5px solid var(--text-secondary);
  color: var(--text-primary);
}

/* --- Section Common --- */
.section {
  padding: var(--space-8) var(--space-4);
}

.section--tight {
  padding: var(--space-6) var(--space-4);
}

.section__inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.section__label {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: var(--space-2);
  display: block;
}

.section__heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: var(--space-4);
}

.section__subheading {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

/* --- Hero Section --- */
.hero {
  position: relative;
  padding: var(--space-8) var(--space-4);
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  background: radial-gradient(ellipse at center, var(--bg-secondary) 0%, var(--bg-primary) 70%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background:
    radial-gradient(circle at 20% 50%, oklch(62.8% 0.258 29.2 / 0.06) 0%, transparent 50%),
    radial-gradient(circle at 80% 50%, oklch(62.8% 0.258 29.2 / 0.04) 0%, transparent 50%);
  pointer-events: none;
}

.hero__content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.hero__title {
  font-family: var(--font-heading);
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  margin-bottom: var(--space-4);
}

.hero__title--red {
  color: var(--red);
}

.hero__text {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 560px;
  margin: 0 auto var(--space-6);
  line-height: 1.7;
}

.hero__actions {
  display: flex;
  gap: var(--space-3);
  justify-content: center;
  flex-wrap: wrap;
}

.hero--page {
  min-height: 35vh;
  padding: var(--space-7) var(--space-4);
}

/* --- Buttons --- */
.btn {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 14px 32px;
  border-radius: var(--radius-sm);
  transition: all var(--ease-default);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  white-space: nowrap;
}

.btn--primary {
  background: var(--red);
  color: var(--text-primary);
}

.btn--primary:hover {
  background: var(--red-hover);
  box-shadow: var(--shadow-red);
  transform: translateY(-1px);
}

.btn--outline {
  border: 2px solid var(--text-primary);
  color: var(--text-primary);
}

.btn--outline:hover {
  border-color: var(--red);
  color: var(--red);
}

.btn--outline-red {
  border: 2px solid var(--red);
  color: var(--red);
}

.btn--outline-red:hover {
  background: var(--red);
  color: var(--text-primary);
}

.btn--lg {
  font-size: 1rem;
  padding: 18px 40px;
  letter-spacing: 0.1em;
}

.btn--sm {
  font-size: 0.75rem;
  padding: 10px 20px;
}

/* --- Cards --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--ease-default);
}

.card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-md);
}

/* --- Two Ways Section --- */
.two-ways {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-5);
}

.two-ways__card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-7) var(--space-5);
  transition: all var(--ease-default);
  position: relative;
  overflow: hidden;
}

.two-ways__card:hover {
  border-color: var(--red);
  box-shadow: var(--shadow-red);
  transform: translateY(-2px);
}

.two-ways__card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--red);
}

.two-ways__icon {
  font-size: 2.5rem;
  margin-bottom: var(--space-3);
}

.two-ways__title {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: var(--space-3);
  color: var(--red);
}

.two-ways__text {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Studio Section --- */
.studio {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
  text-align: center;
}

.studio__text {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto var(--space-6);
  line-height: 1.8;
}

.studio__cta {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--red);
  max-width: 700px;
  margin: 0 auto;
}

/* --- Free Trial CTA --- */
.cta-banner {
  background: var(--red);
  text-align: center;
  padding: var(--space-8) var(--space-4);
}

.cta-banner__heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: var(--space-5);
}

.cta-banner .btn--outline {
  border-color: var(--text-primary);
  color: var(--text-primary);
}

.cta-banner .btn--outline:hover {
  background: var(--text-primary);
  color: var(--red);
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: var(--bg-card);
}

.carousel__track {
  display: flex;
  transition: transform var(--ease-slow);
  will-change: transform;
}

.carousel__slide {
  min-width: 100%;
  position: relative;
}

.carousel__slide img {
  width: 100%;
  height: 500px;
  object-fit: cover;
  filter: brightness(0.7);
}

.carousel__caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-5);
  background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.carousel__caption-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.carousel__controls {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  transform: translateY(-50%);
  display: flex;
  justify-content: space-between;
  padding: 0 var(--space-3);
  pointer-events: none;
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  pointer-events: auto;
  transition: all var(--ease-fast);
  backdrop-filter: blur(4px);
}

.carousel__btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-4);
}

.carousel__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--text-muted);
  transition: all var(--ease-fast);
}

.carousel__dot.active {
  background: var(--red);
  box-shadow: 0 0 8px var(--red-glow);
}

/* --- Toggle (Floor/Treadmill) --- */
.toggle-group {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: var(--space-6);
  background: var(--bg-tertiary);
  border-radius: var(--radius-sm);
  overflow: hidden;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 14px 36px;
  color: var(--text-secondary);
  transition: all var(--ease-default);
  position: relative;
}

.toggle-btn.active {
  background: var(--red);
  color: var(--text-primary);
  box-shadow: var(--shadow-red);
}

.toggle-btn:hover:not(.active) {
  color: var(--text-primary);
}

.toggle-content {
  display: none;
  animation: fadeIn var(--ease-default);
}

.toggle-content.active {
  display: block;
}

/* --- Weekly Schedule Table --- */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: left;
  padding: var(--space-3) var(--space-4);
  color: var(--red);
  border-bottom: 2px solid var(--red);
}

.schedule-table tbody td {
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.schedule-table tbody td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-primary);
}

.schedule-table tbody tr:hover td {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* --- Instructor Grid --- */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-6);
  justify-content: center;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  transition: all var(--ease-fast);
}

.filter-btn:hover {
  color: var(--text-primary);
}

.filter-btn.active {
  background: var(--red);
  color: var(--text-primary);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-4);
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--ease-default);
}

.instructor-card:hover {
  border-color: var(--border-default);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.instructor-card.hidden {
  display: none;
}

.instructor-card__avatar {
  width: 100%;
  height: 240px;
  object-fit: cover;
  background: var(--bg-tertiary);
}

.instructor-card__body {
  padding: var(--space-4);
}

.instructor-card__name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-1);
}

.instructor-card__location {
  font-size: 0.875rem;
  color: var(--text-tertiary);
  margin-bottom: var(--space-3);
}

.instructor-card__cta {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--red);
  transition: opacity var(--ease-fast);
}

.instructor-card__cta:hover {
  opacity: 0.8;
}

/* --- FAQ Accordion --- */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion__item {
  border-bottom: 1px solid var(--border-subtle);
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  text-align: left;
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-primary);
  transition: color var(--ease-fast);
}

.accordion__trigger:hover {
  color: var(--red);
}

.accordion__icon {
  font-size: 1.5rem;
  font-weight: 300;
  transition: transform var(--ease-default);
  color: var(--red);
  flex-shrink: 0;
  margin-left: var(--space-3);
}

