  /* Backgrounds */
  --bg-primary: oklch(8% 0.005 285);
  --bg-secondary: oklch(12% 0.006 285);
  --bg-tertiary: oklch(16% 0.007 285);
  --bg-card: oklch(14% 0.006 285);
  --bg-elevated: oklch(18% 0.007 285);

  /* Text */
  --text-primary: oklch(100% 0 0);
  --text-secondary: oklch(75% 0.01 285);
  --text-tertiary: oklch(55% 0.01 285);
  --text-muted: oklch(45% 0.008 285);

  /* Borders */
  --border-default: oklch(25% 0.01 285);
  --border-subtle: oklch(18% 0.008 285);

  /* Semantic */
  --success: oklch(65% 0.18 145);
  --error: oklch(62.8% 0.258 29.2);

  /* Spacing scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;

  /* Typography */
  --font-heading: 'Oswald', 'Impact', 'Helvetica Neue', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 72px;
  --topbar-height: 40px;

  /* Radii */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.4);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.5);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.6);
  --shadow-red: 0 0 24px oklch(62.8% 0.258 29.2 / 0.25);

  /* Transitions */
  --ease-fast: 150ms ease;
