.two-ways__icon {
  font-size: 2.5rem;
  margin-bottom: var(--space-3);
}

.two-ways__title {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: var(--space-3);
  color: var(--red);
}

.two-ways__text {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Studio Section --- */
.studio {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
  text-align: center;
}

.studio__text {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto var(--space-6);
  line-height: 1.8;
}

.studio__cta {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--red);
  max-width: 700px;
  margin: 0 auto;
}

/* --- Free Trial CTA --- */
.cta-banner {
  background: var(--red);
  text-align: center;
  padding: var(--space-8) var(--space-4);
}

.cta-banner__heading {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: var(--space-5);
}

.cta-banner .btn--outline {
  border-color: var(--text-primary);
  color: var(--text-primary);
}

.cta-banner .btn--outline:hover {
  background: var(--text-primary);
  color: var(--red);
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: var(--bg-card);
}

.carousel__track {
  display: flex;
  transition: transform var(--ease-slow);
  will-change: transform;
}

.carousel__slide {
  min-width: 100%;
  position: relative;
}

.carousel__slide img {
  width: 100%;
  height: 500px;
  object-fit: cover;
  filter: brightness(0.7);
}

.carousel__caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: var(--space-5);
  background: linear-gradient(transparent, rgba(0,0,0,0.8));
}

.carousel__caption-title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.carousel__controls {
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  transform: translateY(-50%);
  display: flex;
  justify-content: space-between;
  padding: 0 var(--space-3);
  pointer-events: none;
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(0,0,0,0.6);
  border: 1px solid rgba(255,255,255,0.2);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  pointer-events: auto;
  transition: all var(--ease-fast);
  backdrop-filter: blur(4px);
}

.carousel__btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-4);
}

.carousel__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--text-muted);
  transition: all var(--ease-fast);
}

.carousel__dot.active {
  background: var(--red);
  box-shadow: 0 0 8px var(--red-glow);
}

/* --- Toggle (Floor/Treadmill) --- */
.toggle-group {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: var(--space-6);
  background: var(--bg-tertiary);
  border-radius: var(--radius-sm);
  overflow: hidden;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 14px 36px;
  color: var(--text-secondary);
  transition: all var(--ease-default);
  position: relative;
}

.toggle-btn.active {
  background: var(--red);
  color: var(--text-primary);
  box-shadow: var(--shadow-red);
}

.toggle-btn:hover:not(.active) {
  color: var(--text-primary);
}

.toggle-content {
  display: none;
  animation: fadeIn var(--ease-default);
}

.toggle-content.active {
  display: block;
}

/* --- Weekly Schedule Table --- */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.schedule-table thead th {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: left;
  padding: var(--space-3) var(--space-4);
  color: var(--red);
  border-bottom: 2px solid var(--red);
}

.schedule-table tbody td {
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.schedule-table tbody td:first-child {
  font-family: var(--font-heading);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-primary);
}

.schedule-table tbody tr:hover td {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* --- Instructor Grid --- */
.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-6);
  justify-content: center;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  transition: all var(--ease-fast);
}

.filter-btn:hover {
  color: var(--text-primary);
}

.filter-btn.active {
  background: var(--red);
  color: var(--text-primary);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-4);
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--ease-default);
}

.instructor-card:hover {
  border-color: var(--border-default);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.instructor-card.hidden {
  display: none;
}

.instructor-card__avatar {
  width: 100%;
  height: 240px;
  object-fit: cover;
  background: var(--bg-tertiary);
}

.instructor-card__body {
  padding: var(--space-4);
}

.instructor-card__name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-1);
}

.instructor-card__location {
  font-size: 0.875rem;
  color: var(--text-tertiary);
  margin-bottom: var(--space-3);
}

.instructor-card__cta {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--red);
  transition: opacity var(--ease-fast);
}

.instructor-card__cta:hover {
  opacity: 0.8;
}

/* --- FAQ Accordion --- */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}

.accordion__item {
  border-bottom: 1px solid var(--border-subtle);
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  text-align: left;
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-primary);
  transition: color var(--ease-fast);
}

.accordion__trigger:hover {
  color: var(--red);
}

.accordion__icon {
  font-size: 1.5rem;
  font-weight: 300;
  transition: transform var(--ease-default);
  color: var(--red);
  flex-shrink: 0;
  margin-left: var(--space-3);
}

.accordion__item.open .accordion__icon {
  transform: rotate(45deg);
}

.accordion__item.open .accordion__trigger {
  color: var(--red);
}

.accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--ease-slow);
}

.accordion__item.open .accordion__content {
  max-height: 300px;
}

.accordion__body {
  padding-bottom: var(--space-4);
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Newsletter --- */
.newsletter {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.newsletter__inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}

.newsletter__heading {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-3);
}

.newsletter__text {
  color: var(--text-secondary);
  margin-bottom: var(--space-5);
  line-height: 1.7;
}

.newsletter__form {
  display: flex;
  gap: var(--space-2);
}

.newsletter__input-wrap {
  flex: 1;
  position: relative;
}

.newsletter__input {
  width: 100%;
  padding: 14px 16px;
  background: var(--bg-tertiary);
  border: 1.5px solid var(--border-default);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.9375rem;
  transition: border-color var(--ease-fast);
}

.newsletter__input::placeholder {
  color: var(--text-muted);
}

.newsletter__input:focus {
  border-color: var(--red);
  outline: none;
}

.newsletter__input.error {
  border-color: var(--error);
}

.newsletter__error {
  position: absolute;
  top: 100%;
  left: 0;
  font-size: 0.8125rem;
  color: var(--error);
  margin-top: var(--space-1);
}

.newsletter__success {
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--success);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: var(--space-4);
}

/* --- Footer --- */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-subtle);
  padding: var(--space-7) var(--space-4) var(--space-5);
}

.footer__inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
  margin-bottom: var(--space-7);
}

.footer__col-title {
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: var(--space-3);
  color: var(--text-secondary);
}

.footer__link {
  display: block;
  font-size: 0.875rem;
  color: var(--text-tertiary);
  padding: var(--space-1) 0;
  transition: color var(--ease-fast);
}

.footer__link:hover {
  color: var(--text-primary);
}

.footer__country-select {
  position: relative;
  width: 100%;
}

.footer__country-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--bg-tertiary);
  border: 1.5px solid var(--border-default);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  color: var(--text-primary);
  transition: border-color var(--ease-fast);
}

.footer__country-trigger:hover {
  border-color: var(--text-secondary);
}

.footer__country-menu {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-1);
  overflow: hidden;
  z-index: 10;
}

.footer__country-menu.open {
  display: block;
}

.footer__country-option {
  display: block;
  width: 100%;
  padding: 10px 16px;
  text-align: left;
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: all var(--ease-fast);
}

.footer__country-option:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-5);
  border-top: 1px solid var(--border-subtle);
  font-size: 0.8125rem;
  color: var(--text-muted);
}

.footer__social {
  display: flex;
  gap: var(--space-3);
  font-size: 0.875rem;
}

.footer__social a {
  color: var(--text-tertiary);
  transition: color var(--ease-fast);
}

.footer__social a:hover {
  color: var(--red);
}

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-4);
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  transition: all var(--ease-default);
}

.feature-card:hover {
  border-color: var(--border-default);
}

.feature-card__icon {
  font-size: 2rem;
  margin-bottom: var(--space-3);
}

.feature-card__title {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-2);
}

.feature-card__text {
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.9375rem;
}

/* --- Method Overview --- */
.method {
  text-align: center;
}

.method__text {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 720px;
  margin: 0 auto;
  line-height: 1.8;
}

/* --- Divider --- */
.divider {
  height: 1px;
  background: var(--border-subtle);
  max-width: var(--max-width);
  margin: 0 auto;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeIn var(--ease-default) both;
}

/* --- Responsive --- */

/* Tablet (≤1024px) */
@media (max-width: 1024px) {
  .nav__links,
  .nav__utility {
    display: none;
  }

  .nav__hamburger {
    display: flex;
  }

  .two-ways {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero {
    min-height: 50vh;
  }
}

/* Mobile (≤640px) */
@media (max-width: 640px) {
  :root {
    --space-7: 48px;
    --space-8: 64px;
  }

  .nav__inner {
    padding: 0 var(--space-3);
  }

  .section {
    padding: var(--space-6) var(--space-3);
  }

  .hero {
    min-height: 45vh;
    padding: var(--space-6) var(--space-3);
  }

  .hero__title {
    font-size: clamp(1.75rem, 8vw, 2.5rem);
  }

  .hero__actions {
    flex-direction: column;
    align-items: center;
  }

  .hero__actions .btn {
    width: 100%;
    max-width: 320px;
  }

  .footer__grid {
    grid-template-columns: 1fr;
    gap: var(--space-5);
  }

  .footer__bottom {
    flex-direction: column;
    gap: var(--space-3);
    text-align: center;
  }

  .newsletter__form {
    flex-direction: column;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .carousel__slide img {
    height: 300px;
  }

  .toggle-btn {
    padding: 12px 24px;
  }

  .btn {
    padding: 12px 24px;
    font-size: 0.8125rem;
  }

  .btn--lg {
    padding: 16px 32px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  html {
    scroll-behavior: auto;
  }
}
